import {
  Mjml,
  MjmlBody,
  MjmlColumn,
  MjmlFont,
  MjmlHead,
  MjmlImage,
  MjmlPreview,
  MjmlSection,
  MjmlSpacer,
  MjmlStyle,
  MjmlTable,
  MjmlText,
} from "@faire/mjml-react";

import type { EmailTheme } from "@/components/email/email-theme";
import { emailAsset } from "@/components/email/email-assets";
import { defaultTheme } from "@/components/email/theme-default";

export type TestimonialLayout = "full-width" | "centered" | "split";
export type TestimonialAlignment = "left" | "center";
export type TestimonialAppearance = "plain" | "boxed" | "accent";
export type TestimonialAvatarTreatment = "inline" | "overlapping";
export type TestimonialPlacement = "left" | "right" | "top" | "bottom";
export type TestimonialVariant = "quote" | "text-top" | "text-bottom";

export interface TestimonialProps {
  theme?: EmailTheme;
  quote?: string;
  author?: string;
  role?: string;
  company?: string;
  avatar?: {
    src: string;
    alt?: string;
  };
  logo?: {
    src: string;
    alt?: string;
  };
  layout?: TestimonialLayout;
  alignment?: TestimonialAlignment;
  appearance?: TestimonialAppearance;
  avatarTreatment?: TestimonialAvatarTreatment;
  placement?: TestimonialPlacement;
  variant?: TestimonialVariant;
  action?: {
    href: string;
    label: string;
  };
}

const fontFamily =
  'Inter, ui-sans-serif, system-ui, -apple-system, "Segoe UI", sans-serif';

const assetUrl = (file: string) => emailAsset(`testimonials/${file}`);

const responsiveStyles = `
  @media only screen and (max-width: 599px) {
    .testimonial-centered-column > table > tbody > tr > td {
      padding-left: 24px !important;
      padding-right: 24px !important;
    }
    .testimonial-centered-quote div {
      font-size: 24px !important;
      line-height: 32px !important;
    }
    .testimonial-avatar-top,
    .testimonial-avatar-bottom {
      overflow: visible !important;
    }
  }
  .testimonial-avatar-top { max-height: 32px !important; }
  .testimonial-avatar-bottom { max-height: 8px !important; }
`;

const AvatarImage = ({
  align = "left",
  alt = "",
  cssClass,
  src,
}: {
  align?: TestimonialAlignment;
  alt?: string;
  cssClass?: string;
  src: string;
}) => (
  <MjmlImage
    align={align}
    alt={alt}
    borderRadius="9999px"
    cssClass={cssClass}
    padding="0"
    src={src}
    width="64px"
  />
);

const CenteredTestimonial = ({
  action,
  author,
  avatar,
  company,
  quote,
  role,
  variant,
}: Required<
  Pick<TestimonialProps, "author" | "company" | "quote" | "role" | "variant">
> &
  Pick<TestimonialProps, "action" | "avatar">) => (
  <MjmlSection backgroundColor="#fffffe" padding="44px 44px">
    <MjmlColumn cssClass="testimonial-centered-column" padding="0">
      {variant === "quote" ? (
        <>
          <MjmlImage
            align="center"
            alt=""
            padding="0"
            src={assetUrl("quote.png")}
            width="36px"
          />
          <MjmlSpacer height="24px" />
        </>
      ) : null}
      <MjmlText
        align="center"
        color="#030712"
        cssClass="testimonial-centered-quote"
        fontFamily={fontFamily}
        fontSize="30px"
        fontWeight="600"
        lineHeight="36px"
        padding="0"
      >
        {quote}
      </MjmlText>
      <MjmlSpacer height="24px" />
      <AvatarImage
        align="center"
        alt={avatar?.alt}
        src={avatar?.src ?? assetUrl("user-1.jpg")}
      />
      <MjmlSpacer height="8px" />
      <MjmlText
        align="center"
        color="#4b5563"
        fontFamily={fontFamily}
        fontSize="16px"
        fontWeight="600"
        lineHeight="24px"
        padding="0"
      >
        {author}, <br />
        {role} at {company}
      </MjmlText>
      <MjmlSpacer height="24px" />
      <MjmlText
        align="center"
        fontFamily={fontFamily}
        fontSize="16px"
        fontWeight="500"
        lineHeight="24px"
        padding="0"
      >
        <a
          href={action?.href ?? "https://example.com"}
          style={{ color: "#4f46e5", textDecoration: "none" }}
        >
          {action?.label ?? `Read ${company}'s case study`}
        </a>
      </MjmlText>
    </MjmlColumn>
  </MjmlSection>
);

const SplitIdentity = ({
  author,
  avatar,
  company,
}: Required<Pick<TestimonialProps, "author" | "company">> &
  Pick<TestimonialProps, "avatar">) => (
  <MjmlColumn padding="0" verticalAlign="top" width="104px">
    <AvatarImage
      alt={avatar?.alt}
      src={avatar?.src ?? assetUrl("user-1.jpg")}
    />
    <MjmlSpacer height="8px" />
    <MjmlText
      color="#030712"
      fontFamily={fontFamily}
      fontSize="16px"
      fontWeight="600"
      lineHeight="24px"
      padding="0"
    >
      {author}, <br />
      <span style={{ color: "#4b5563" }}>{company}</span>
    </MjmlText>
  </MjmlColumn>
);

const SplitQuote = ({
  action,
  company,
  quote,
}: Required<Pick<TestimonialProps, "company" | "quote">> &
  Pick<TestimonialProps, "action">) => (
  <MjmlColumn padding="0" verticalAlign="top">
    <MjmlImage
      align="left"
      alt=""
      padding="0"
      src={assetUrl("quote.png")}
      width="36px"
    />
    <MjmlSpacer height="24px" />
    <MjmlText
      color="#030712"
      fontFamily={fontFamily}
      fontSize="20px"
      fontWeight="600"
      lineHeight="28px"
      padding="0"
    >
      {quote}
    </MjmlText>
    <MjmlSpacer height="24px" />
    <MjmlText
      fontFamily={fontFamily}
      fontSize="16px"
      fontWeight="500"
      lineHeight="24px"
      padding="0"
    >
      <a
        href={action?.href ?? "https://example.com"}
        style={{ color: "#4f46e5", textDecoration: "none" }}
      >
        {action?.label ?? `Read ${company}'s case study`}
      </a>
    </MjmlText>
  </MjmlColumn>
);

const SplitGap = () => (
  <MjmlColumn padding="0" width="44px">
    <MjmlSpacer height="24px" />
  </MjmlColumn>
);

const SplitTestimonial = ({
  action,
  author,
  avatar,
  company,
  placement,
  quote,
}: Required<
  Pick<TestimonialProps, "author" | "company" | "placement" | "quote">
> &
  Pick<TestimonialProps, "action" | "avatar">) => (
  <MjmlSection backgroundColor="#fffffe" padding="44px 24px">
    {placement === "right" ? (
      <SplitQuote action={action} company={company} quote={quote} />
    ) : (
      <SplitIdentity author={author} avatar={avatar} company={company} />
    )}
    <SplitGap />
    {placement === "right" ? (
      <SplitIdentity author={author} avatar={avatar} company={company} />
    ) : (
      <SplitQuote action={action} company={company} quote={quote} />
    )}
  </MjmlSection>
);

const InlineIdentity = ({
  alignment,
  author,
  avatar,
  role,
}: Required<Pick<TestimonialProps, "alignment" | "author" | "role">> &
  Pick<TestimonialProps, "avatar">) => {
  if (alignment === "center") {
    return (
      <>
        <AvatarImage
          align="center"
          alt={avatar?.alt}
          src={avatar?.src ?? assetUrl("user-2.jpg")}
        />
        <MjmlSpacer height="12px" />
        <MjmlText
          align="center"
          color="#030712"
          fontFamily={fontFamily}
          fontSize="16px"
          fontWeight="600"
          lineHeight="24px"
          padding="0"
        >
          {author}, <br />
          <span style={{ color: "#4b5563" }}>{role}</span>
        </MjmlText>
      </>
    );
  }

  return (
    <MjmlTable
      cellpadding="0"
      cellspacing="0"
      fontFamily={fontFamily}
      padding="0"
      role="presentation"
    >
      <tbody>
        <tr>
          <td style={{ width: "64px" }}>
            <img
              alt={avatar?.alt ?? ""}
              src={avatar?.src ?? assetUrl("user-2.jpg")}
              width="64"
              style={{ borderRadius: "9999px", verticalAlign: "middle" }}
            />
          </td>
          <td style={{ width: "12px" }}>&zwj;</td>
          <td
            style={{
              color: "#030712",
              fontFamily,
              fontSize: "16px",
              fontWeight: 600,
              lineHeight: "24px",
            }}
          >
            {author}, <br />
            <span style={{ color: "#4b5563" }}>{role}</span>
          </td>
        </tr>
      </tbody>
    </MjmlTable>
  );
};

const FullWidthTestimonial = ({
  alignment,
  appearance,
  author,
  avatar,
  logo,
  quote,
  role,
}: Required<
  Pick<
    TestimonialProps,
    "alignment" | "appearance" | "author" | "quote" | "role"
  >
> &
  Pick<TestimonialProps, "avatar" | "logo">) => {
  const accent = appearance === "accent";
  let defaultLogo = "logo-monarch.png";
  let logoWidth = "145px";
  if (alignment === "center") {
    defaultLogo = "logo-accentic.png";
    logoWidth = "106px";
  }
  if (accent) {
    defaultLogo = "logo-accentic-light.png";
    logoWidth = "106px";
  }
  const boxed = appearance !== "plain";
  const cardBackgroundColor = accent ? "#030712" : "#f8fafc";

  return (
    <MjmlSection
      backgroundColor="#fffffe"
      padding={`44px ${alignment === "center" && !boxed ? "44px" : "24px"}`}
    >
      <MjmlColumn
        backgroundColor={boxed ? cardBackgroundColor : undefined}
        borderRadius={boxed ? "8px" : undefined}
        cssClass={boxed ? "testimonial-centered-column" : undefined}
        padding={boxed ? "24px 44px" : "0"}
      >
        <MjmlImage
          align={alignment}
          alt={logo?.alt ?? ""}
          padding="0"
          src={logo?.src ?? assetUrl(defaultLogo)}
          width={logoWidth}
        />
        <MjmlSpacer height="24px" />
        <MjmlText
          align={alignment}
          color={accent ? "#fffffe" : "#030712"}
          fontFamily={fontFamily}
          fontSize="18px"
          fontWeight="600"
          lineHeight="28px"
          padding="0"
        >
          {quote}
        </MjmlText>
        <MjmlSpacer height="24px" />
        <InlineIdentity
          alignment={alignment}
          author={author}
          avatar={avatar}
          role={role}
        />
      </MjmlColumn>
    </MjmlSection>
  );
};

const OverlappingTestimonial = ({
  alignment,
  author,
  avatar,
  logo,
  placement,
  quote,
  role,
}: Required<
  Pick<
    TestimonialProps,
    "alignment" | "author" | "placement" | "quote" | "role"
  >
> &
  Pick<TestimonialProps, "avatar" | "logo">) => (
  <MjmlSection
    backgroundColor="#fffffe"
    padding={`44px ${alignment === "center" ? "44px" : "24px"}`}
  >
    <MjmlColumn
      backgroundColor="#f8fafc"
      borderRadius="8px"
      cssClass="testimonial-centered-column"
      padding="0 44px 24px"
    >
      {placement === "top" ? (
        <AvatarImage
          align={alignment}
          alt={avatar?.alt}
          cssClass="testimonial-avatar-top"
          src={avatar?.src ?? assetUrl("user-2.jpg")}
        />
      ) : null}
      <MjmlSpacer height="48px" />
      <MjmlText
        align={alignment}
        color="#030712"
        fontFamily={fontFamily}
        fontSize="18px"
        fontWeight="600"
        lineHeight="28px"
        padding="0"
      >
        {quote}
      </MjmlText>
      <MjmlSpacer height="24px" />
      <MjmlImage
        align={alignment}
        alt={logo?.alt ?? ""}
        padding="0"
        src={logo?.src ?? assetUrl("logo-accentic.png")}
        width="106px"
      />
      <MjmlSpacer height="24px" />
      <MjmlText
        align={alignment}
        color="#030712"
        fontFamily={fontFamily}
        fontSize="16px"
        fontWeight="600"
        lineHeight="24px"
        padding="0"
      >
        {author}, <br />
        <span style={{ color: "#4b5563" }}>{role}</span>
      </MjmlText>
      {placement === "bottom" ? (
        <>
          <MjmlSpacer height="24px" />
          <AvatarImage
            align={alignment}
            alt={avatar?.alt}
            cssClass="testimonial-avatar-bottom"
            src={avatar?.src ?? assetUrl("user-2.jpg")}
          />
        </>
      ) : null}
    </MjmlColumn>
  </MjmlSection>
);

const TestimonialSection = ({
  action,
  alignment = "left",
  appearance = "plain",
  author,
  avatar,
  avatarTreatment = "inline",
  company = "Monarch",
  layout = "full-width",
  logo,
  placement,
  quote,
  role,
  variant = "quote",
}: Omit<TestimonialProps, "theme">) => {
  if (layout === "centered") {
    return (
      <CenteredTestimonial
        action={action}
        author={author ?? "Jason Adam"}
        avatar={avatar}
        company={company}
        quote={
          quote ??
          "After redesigning our emails with emailcn, we saw an increase in engagement by 40%."
        }
        role={role ?? "Director of Operations"}
        variant={variant}
      />
    );
  }

  if (layout === "split") {
    return (
      <SplitTestimonial
        action={action}
        author={author ?? "Jason Adam"}
        avatar={avatar}
        company={company}
        placement={placement === "right" ? "right" : "left"}
        quote={
          quote ??
          "After migrating to emailcn, we increased efficiency by 40% across our transactional and marketing email development pipeline."
        }
      />
    );
  }

  const resolvedAuthor = author ?? "Ella Roustek";
  const resolvedQuote =
    quote ??
    "“After migrating to emailcn, we increased efficiency by 40% across our transactional and marketing email development pipeline.”";
  const resolvedRole = role ?? "Operations Manager";

  if (avatarTreatment === "overlapping") {
    return (
      <OverlappingTestimonial
        alignment={alignment}
        author={resolvedAuthor}
        avatar={avatar}
        logo={logo}
        placement={placement === "top" ? "top" : "bottom"}
        quote={resolvedQuote}
        role={resolvedRole}
      />
    );
  }

  return (
    <FullWidthTestimonial
      alignment={alignment}
      appearance={appearance}
      author={resolvedAuthor}
      avatar={avatar}
      logo={logo}
      quote={resolvedQuote}
      role={resolvedRole}
    />
  );
};

export const Testimonial = ({
  theme = defaultTheme,
  ...props
}: TestimonialProps) => (
  <Mjml>
    <MjmlHead>
      <MjmlFont href="https://rsms.me/inter/inter.css" name="Inter" />
      <MjmlPreview>Customer testimonial</MjmlPreview>
      <MjmlStyle>{responsiveStyles}</MjmlStyle>
    </MjmlHead>
    <MjmlBody backgroundColor="#f1f5f9" width={theme.containerWidth}>
      <TestimonialSection {...props} />
    </MjmlBody>
  </Mjml>
);

Testimonial.PreviewProps = {
  alignment: "left",
  appearance: "plain",
  avatarTreatment: "inline",
  layout: "full-width",
  placement: "bottom",
  theme: defaultTheme,
  variant: "quote",
} satisfies TestimonialProps;

const ASSET_ORIGIN = "https://www.emailcn.run";
const ICONS8_ORIGIN = "https://img.icons8.com";
const UNSPLASH_ORIGIN = "https://images.unsplash.com";

const portraitIds = [
  "photo-1500648767791-00dcc994a43e",
  "photo-1507003211169-0a1dd7228f2d",
  "photo-1494790108377-be9c29b29330",
  "photo-1438761681033-6461ffad8d80",
  "photo-1534528741775-53994a69daeb",
  "photo-1506794778202-cad84cf45f1c",
] as const;

const productIds = [
  "photo-1521572163474-6864f9cf17ab",
  "photo-1503341504253-dff4815485f1",
  "photo-1576566588028-4147f3842f27",
  "photo-1562157873-818bc0726f68",
] as const;

const socialIconSlugs = {
  discord: "discord-logo",
  facebook: "facebook-new",
  github: "github",
  instagram: "instagram-new",
  linkedin: "linkedin",
  slack: "slack-new",
  x: "twitterx--v1",
  youtube: "youtube-play",
} as const;

const brandIconSlugs = [
  [/(?:btc|bitcoin)/i, "bitcoin--v1"],
  [/(?:eth|ethereum)/i, "ethereum"],
  [/visa/i, "visa"],
  [/mastercard/i, "mastercard-logo"],
  [/apple-pay/i, "apple-pay"],
  [/google-pay/i, "google-pay"],
  [/klarna/i, "klarna"],
  [/stripe/i, "stripe"],
  [/fedex/i, "fedex"],
  [/north-face/i, "the-north-face"],
] as const;

const hashString = (value: string) => {
  let hash = 7;

  for (const character of value) {
    hash = (hash * 31 + (character.codePointAt(0) ?? 0)) % 2_147_483_647;
  }

  return hash;
};

const getDimensions = (path: string) => {
  if (/teams\/member-\d+-lg/i.test(path)) {
    return [800, 560] as const;
  }
  if (/teams\/member-\d+/i.test(path)) {
    return [600, 600] as const;
  }
  if (/(?:avatar|user|headshot)/i.test(path)) {
    return [160, 160] as const;
  }
  if (/(?:logo|insignia)/i.test(path)) {
    return [320, 96] as const;
  }
  if (/(?:badge-app|badge-google)/i.test(path)) {
    return [260, 80] as const;
  }
  if (/(?:icon|btc|eth)/i.test(path)) {
    return [64, 64] as const;
  }
  if (/(?:portrait|member|team)/i.test(path)) {
    return [600, 800] as const;
  }
  if (/(?:square|product|shopping-cart)/i.test(path)) {
    return [700, 700] as const;
  }
  if (/(?:hero|footer|background|bg-|overlay|full-width)/i.test(path)) {
    return [1200, 700] as const;
  }
  if (/(?:strip|landscape|bento|category-preview)/i.test(path)) {
    return [800, 520] as const;
  }

  return [800, 600] as const;
};

const getSeed = (path: string) =>
  `emailcn-${path
    .replace(/\.[^.]+$/, "")
    .replaceAll(/[^a-z0-9]+/gi, "-")
    .replaceAll(/^-|-$/g, "")
    .toLowerCase()}`;

const getIndexedAsset = (path: string, assets: readonly string[]) => {
  const explicitIndex = path.match(
    /(?:member|avatar|product-list|shopping-cart)-(\d+)/i
  )?.[1];
  const index = explicitIndex
    ? Number.parseInt(explicitIndex, 10) - 1
    : hashString(path);

  return assets[((index % assets.length) + assets.length) % assets.length];
};

const getUnsplashAsset = (id: string, width: number, height: number) =>
  `${UNSPLASH_ORIGIN}/${id}?auto=format&fit=crop&w=${width}&h=${height}&q=80`;

const getIcons8Asset = (
  slug: string,
  {
    color,
    style = "ios-filled",
  }: {
    color?: string;
    style?: "color" | "ios" | "ios-filled";
  } = {}
) =>
  color
    ? `${ICONS8_ORIGIN}/${style}/50/${color}/${slug}.png`
    : `${ICONS8_ORIGIN}/${style}/50/${slug}.png`;

const getStoreBadgeAsset = (path: string) => {
  if (/badge-app-store/i.test(path)) {
    return "https://developer.apple.com/assets/elements/badges/download-on-the-app-store.svg";
  }
  if (/badge-google-play/i.test(path)) {
    return "https://play.google.com/intl/en_us/badges/static/images/badges/en_badge_web_generic.png";
  }
};

const getSocialIconAsset = (path: string) => {
  const isLight = /(?:-light|check-white)/i.test(path);
  const foreground = isLight ? "FFFFFF" : "111827";

  for (const [name, slug] of Object.entries(socialIconSlugs)) {
    if (new RegExp(`(?:^|[-/])${name}(?:[-.]|$)`, "i").test(path)) {
      return getIcons8Asset(slug, { color: foreground });
    }
  }
};

const getUtilityIconAsset = (path: string) => {
  const isLight = /(?:-light|check-white)/i.test(path);
  const foreground = isLight ? "FFFFFF" : "111827";

  if (/star-half/i.test(path)) {
    return getIcons8Asset("star-half-empty", { color: "374151" });
  }
  if (/star-solid/i.test(path)) {
    return getIcons8Asset("star--v1", { color: "374151" });
  }
  if (/edit/i.test(path)) {
    return getIcons8Asset("edit--v1", {
      color: "4F46E5",
      style: "ios",
    });
  }
  if (/arrow-right/i.test(path)) {
    return getIcons8Asset("long-arrow-right--v1", {
      color: "4F46E5",
      style: "ios",
    });
  }
  if (/chevron-right/i.test(path)) {
    return getIcons8Asset("chevron-right", {
      color: "4F46E5",
      style: "ios",
    });
  }
  if (/check/i.test(path)) {
    return getIcons8Asset("checkmark--v1", { color: foreground });
  }
};

const getBrandIconAsset = (path: string) => {
  const match = brandIconSlugs.find(([pattern]) => pattern.test(path));

  return match
    ? getIcons8Asset(match[1], {
        style: "color",
      })
    : undefined;
};

const getWordmarkAsset = (path: string) => {
  const isLight = /light/i.test(path);
  const background = isLight ? "030712" : "FFFFFF";
  const foreground = isLight ? "FFFFFF" : "111827";

  return `https://placehold.co/320x96/${background}/${foreground}.png?text=EMAILCN`;
};

const getIconAsset = (path: string) =>
  getStoreBadgeAsset(path) ??
  getSocialIconAsset(path) ??
  getUtilityIconAsset(path) ??
  getBrandIconAsset(path);

export const emailAsset = (path: string) => {
  const normalizedPath = path.replace(/^\/+/, "");

  if (
    normalizedPath === "bento-grids/trend.png" ||
    normalizedPath === "bento-grids/trend-sm.png"
  ) {
    return `${ASSET_ORIGIN}/email-assets/${normalizedPath}`;
  }

  const iconAsset = getIconAsset(normalizedPath);
  if (iconAsset) {
    return iconAsset;
  }

  const seed = getSeed(normalizedPath);
  const [width, height] = getDimensions(normalizedPath);

  if (/teams\/hero/i.test(normalizedPath)) {
    return getUnsplashAsset("photo-1521737711867-e3b97375f902", width, height);
  }

  if (/(?:avatar|user|headshot|member|team)/i.test(normalizedPath)) {
    return getUnsplashAsset(
      getIndexedAsset(normalizedPath, portraitIds),
      width,
      height
    );
  }

  if (/products\/shoe/i.test(normalizedPath)) {
    return getUnsplashAsset("photo-1542291026-7eec264c27ff", width, height);
  }

  if (/products\/phone/i.test(normalizedPath)) {
    return getUnsplashAsset("photo-1511707171634-5f897ff02aa9", width, height);
  }

  if (
    /(?:product-detail|product-lists|products\/product|shopping-cart)/i.test(
      normalizedPath
    )
  ) {
    return getUnsplashAsset(
      getIndexedAsset(normalizedPath, productIds),
      width,
      height
    );
  }

  if (/(?:trend|chart)/i.test(normalizedPath)) {
    return `${ASSET_ORIGIN}/email-assets/bento-grids/trend.png`;
  }

  if (/(?:emailcn|maizzle|logo|insignia)/i.test(normalizedPath)) {
    return getWordmarkAsset(normalizedPath);
  }

  return `https://picsum.photos/seed/${encodeURIComponent(
    seed
  )}/${width}/${height}.jpg`;
};
